import {
  type CheckboxGroup as CheckboxGroupController,
  type CheckboxGroupOptions,
  createCheckboxGroup,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { For, merge, omit, Show, untrack } from "solid-js";

import { Checkbox } from "./checkbox.tsx";
import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

export interface CheckboxGroupProps<T>
  extends Omit<CheckboxGroupOptions<T>, "values">, Renderable<PartProps, void> {
  /** The three values the primitive takes: its controller is a tri-state, so the group is exactly three boxes. */
  readonly values: readonly [T, T, T];
  /** The tri-state "all" checkbox above the items, as `parentChecked` derives it. */
  readonly parent?: boolean;
  readonly parentLabel?: string;
  /** One label per value; the index is the box's. */
  readonly children: (value: T, index: number) => JSX.Element;
  readonly class?: string;
  /** The primitive, once: a page that reads the checked set as well as shows it. */
  readonly onReady?: (group: CheckboxGroupController<T>) => void;
}

const groupClass = css.cn(css.display("flex"), css.flexDirection("column"), css.gap(t.space._2));
const errorClass = css.cn(css.fontSize(t.font.sizeSm), css.color(t.color.invalid));

// The primitive's `childProps` are a role=checkbox of its own, with its own focus model; the kit's `Checkbox` is that
// control already, so its state is the primitive's bit and its activation is the primitive's `click`. The one thing the
// group keeps from `groupProps` is its ARIA (role, id, name, description, invalid state); the primitive's Tab wraps inside
// the group, and a box that owns its own focus keeps the browser's order instead.
const CHILDREN = ["c0", "c1", "c2"] as const;

/**
 * APG checkbox group, styled: `role="group"` with a name, the kit's `Checkbox` per value, and — with `parent` — the
 * tri-state "all" box whose `aria-checked` is derived from the three. `createCheckboxGroup` owns the checked subset (packed
 * into one value), the all/none/mixed derivation, the "remember the last mixed combination" cycle, the toggling, and the
 * name / description / error contract (`label` or `labelledby`, `describedby`, `invalid`, `error`): the group announces
 * what the primitive says, and the error element it names is rendered here.
 *
 * `value` makes it controlled; without it the group owns the subset. `onValueChange` is a request the host may ignore.
 */
export const CheckboxGroup = <T,>(props: CheckboxGroupProps<T>): JSX.Element => {
  const group = createCheckboxGroup<T>({
    values: props.values,
    get value() {
      return props.value;
    },
    defaultValue: props.defaultValue,
    parent: props.parent,
    remember: props.remember,
    get id() {
      return props.id;
    },
    get label() {
      return props.label;
    },
    get labelledby() {
      return props.labelledby;
    },
    get describedby() {
      return props.describedby;
    },
    get invalid() {
      return props.invalid;
    },
    get error() {
      return props.error;
    },
    get onValueChange() {
      return props.onValueChange;
    },
    get onFocus() {
      return props.onFocus;
    },
    get onBlur() {
      return props.onBlur;
    },
  });
  untrack(() => props.onReady)?.(group);

  const own = {
    "data-part": "checkbox-group",
    get class() {
      return css.cn(groupClass, props.class);
    },
  } as PartProps;

  return (
    <>
      {renderPart(props, merge(omit(group.groupProps, "onKeyDown"), own), undefined, (part) => (
        <div {...part}>
          <Show when={props.parent}>
            <Checkbox
              allowMixed
              value={group.parentChecked()}
              onValueChange={() => group.click("parent")}
            >
              {props.parentLabel ?? "All"}
            </Checkbox>
          </Show>
          <For each={props.values}>
            {(value, index) => (
              <Checkbox
                value={group.children()[index()] === true ? "true" : "false"}
                onValueChange={() => group.click(CHILDREN[index()] ?? "c0")}
              >
                {props.children(value, index())}
              </Checkbox>
            )}
          </For>
        </div>
      ))}
      {/* the primitive's `aria-describedby` names this element while it has an error: render it always, it is `hidden`
          when there is none, and `role="alert"` while it is shown */}
      <p {...group.errorProps} data-part="checkbox-group-error" class={errorClass}>
        {group.error()}
      </p>
    </>
  );
};

import {
  type Checkbox as CheckboxController,
  type CheckboxOptions,
  createCheckbox,
} from "@cssints/headless";
import { untrack } from "solid-js";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };

import { t } from "./theme.ts" with { type: "cssints" };

/** APG checkbox, styled: a box, a check and the label beside it. */
export interface CheckboxProps extends Omit<CheckboxOptions, "id"> {
  readonly children?: JSX.Element;
  /** The primitive, once: a scenario fixture needs it; a page rarely does. */
  readonly onReady?: (checkbox: CheckboxController) => void;
}

const root = css.cn(
  css.group(),
  css.display("inline-flex"),
  css.alignItems("center"),
  css.gap(t.space._2),
  css.fontSize(t.font.size),
  css.color(t.color.text),
  css.cursor("pointer"),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
  css.attr("aria-disabled", "true")(css.color(t.color.textDisabled), css.cursor("not-allowed")),
);

const box = css.cn(
  css.display("inline-grid"),
  css.placeItems("center"),
  css.width("1.125rem"),
  css.height("1.125rem"),
  css.border("1px solid", t.color.border),
  css.borderRadius("4px"),
  css.bg(t.color.surface),
  css.transition("background-color 120ms, border-color 120ms"),
  css.attr("aria-checked", "true")(
    css.bg(t.color.highlight),
    css.border("1px solid", t.color.highlight),
    css.color(t.color.onHighlight),
  ),
  css.attr("aria-checked", "mixed")(
    css.bg(t.color.highlight),
    css.border("1px solid", t.color.highlight),
  ),
);

const mark = css.cn(
  css.fontSize("0.75rem"),
  css.within(css.attr("aria-checked", "false"))(css.display("none")),
);

export const Checkbox = (props: CheckboxProps): JSX.Element => {
  const checkbox = createCheckbox({
    get value() {
      return props.value;
    },
    defaultValue: props.defaultValue,
    get allowMixed() {
      return props.allowMixed;
    },
    get disabled() {
      return props.disabled;
    },
    get readOnly() {
      return props.readOnly;
    },
    get onValueChange() {
      return props.onValueChange;
    },
  });
  untrack(() => props.onReady)?.(checkbox);
  return (
    <div
      {...checkbox.checkboxProps}
      data-part="checkbox"
      class={root}
      onClick={(event) => {
        checkbox.checkboxProps.onClick();
        // a div is not focused by a click the way a native control is
        event.currentTarget.focus();
      }}
    >
      <span aria-hidden="true" class={box}>
        <span class={mark}>✓</span>
      </span>
      {props.children}
    </div>
  );
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import {
  type CheckboxGroup as CheckboxGroupController,
  type CheckboxGroupFocus,
} from "@cssints/headless";
import type { CheckboxGroupConfig } from "@cssints/apg-specs/apg/checkbox-group.bridge";
import type { Json } from "@cssints/apg-specs/scenario";
import type { Mounted } from "./checkbox-group-driver.ts";
import { CheckboxGroup as StyledCheckboxGroup } from "./checkbox-group.tsx";
import { createSignal } from "solid-js";
import { render } from "@solidjs/web";

const domLabel = (target: CheckboxGroupFocus): string =>
  target === "parent" ? "checkbox:parent" : `checkbox:${target.slice(1)}`;

/**
 * Mounts the styled checkbox group for the scenario walk. The group is the skin's
 * `data-part="checkbox-group"`, the controller and the three children are the kit's
 * `Checkbox` (`data-part="checkbox"`, in DOM order: the parent first). The spec's parent arm
 * exists in every configuration, so the fixture keeps the parent box mounted even when the
 * scenario's `parent` is false; that config only sets the starting "remember" value.
 *
 * Controlled, the fixture is the host: it keeps the checked set in a signal, passes it as
 * `value`, and either writes every request back (`accepts`) or ignores it.
 */
export const mountCheckboxGroup = (config: CheckboxGroupConfig): Mounted => {
  const root = document.createElement("div");
  document.body.append(root);
  const events = new Map<string, Json[]>();
  const values: readonly [Json, Json, Json] = config.values as readonly [Json, Json, Json];
  const labelsFor = (children: ReadonlyArray<boolean>): ReadonlyArray<Json> =>
    children.flatMap((checked, index) => {
      const value = values[index];
      return checked && value !== undefined ? [value] : [];
    });
  const bitsFor = (value: Json | undefined): ReadonlyArray<boolean> => {
    if (typeof value === "boolean") {
      return [value, false, false];
    }
    if (typeof value === "number") {
      return [0, 1, 2].map((index) => Math.floor(value / 2 ** index) % 2 === 1);
    }
    if (Array.isArray(value)) {
      return [0, 1, 2].map((index) => value[index] === true);
    }
    throw new Error(`setValue needs a value, got ${JSON.stringify(value)}`);
  };
  const [host, setHost] = createSignal<ReadonlyArray<boolean>>(config.children);
  let api: CheckboxGroupController<Json> | undefined;

  const focusTarget = (target: CheckboxGroupFocus): void => {
    if (target === "none") {
      const active = document.activeElement;
      if (active instanceof HTMLElement && root.contains(active)) {
        active.blur();
      }
      return;
    }
    // the bridge names the parent `checkbox:parent`; the skin's four boxes are one part, in order
    const index = target === "parent" ? 0 : Number(target.slice(1)) + 1;
    [...root.querySelectorAll<HTMLElement>('[data-part="checkbox"]')][index]?.focus();
  };

  // Solid flushes signal writes on a microtask; read focus after the flush.
  const scheduleFocus = (): void => {
    queueMicrotask(() => {
      focusTarget(api?.focused() ?? "none");
    });
  };

  const dispose = render(() => {
    return (
      <StyledCheckboxGroup
        label="Channels"
        values={values}
        parent
        value={config.controlled ? labelsFor(host()) : undefined}
        defaultValue={labelsFor(config.children)}
        remember={config.remember}
        onReady={(group) => {
          api = group;
        }}
        onValueChange={(checked) => {
          events.set("onValueChange", [checked]);
          if (config.accepts) {
            setHost(values.map((value) => checked.includes(value)));
          }
        }}
      >
        {(value) => String(value)}
      </StyledCheckboxGroup>
    );
  }, root);

  return {
    root,
    events,
    value: () => api?.checkedValues() ?? [],
    focus: () => {
      const focus = api?.focused() ?? "none";
      return focus === "none" ? null : domLabel(focus);
    },
    setProp: (name, value) => {
      switch (name) {
        case "focus": {
          if (typeof value !== "string") {
            throw new Error(`focus needs a target, got ${JSON.stringify(value)}`);
          }
          api?.focusOn(value as CheckboxGroupFocus);
          scheduleFocus();
          break;
        }
        case "blur":
          api?.blur();
          focusTarget("none");
          break;
        case "key": {
          const key =
            typeof value === "object" && value !== null && !Array.isArray(value)
              ? (value as Readonly<Record<string, Json>>)["key"]
              : undefined;
          if (key === "Tab") {
            api?.keyTab();
          } else if (key === " " || key === "Space") {
            api?.keySpace();
          } else {
            throw new Error(`unsupported key ${JSON.stringify(key)}`);
          }
          scheduleFocus();
          break;
        }
        case "click": {
          if (typeof value !== "string") {
            throw new Error(`click needs a target, got ${JSON.stringify(value)}`);
          }
          api?.click(value as CheckboxGroupFocus);
          scheduleFocus();
          break;
        }
        case "remember":
          api?.setRemember(value === true);
          break;
        case "setValue":
          setHost(bitsFor(value));
          break;
        case "hostToggle":
          setHost(host().map((checked, index) => (index === 0 ? !checked : checked)));
          break;
        default:
          throw new Error(`fixture has no prop ${name}`);
      }
    },
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { type ActionStep, type Driver, type Json, Unsupported } from "@cssints/apg-specs/scenario";
import { flush } from "solid-js";
import { userEvent } from "vite-plus/test/browser";

/**
 * The generic DOM side of the scenario bridge. A pattern's fixture renders its
 * parts with `data-part="<name>"` and returns a `Mounted`; this turns scenario
 * steps into real pointer/keyboard input and DOM reads into observations.
 */
export interface Mounted {
  readonly root: HTMLElement;
  /** Apply a scenario `prop` step (programmatic input) to the mounted widget. */
  readonly setProp: (name: string, value: Json | undefined) => void;
  /** Callback payloads, recorded under their canonical name. */
  readonly events: ReadonlyMap<string, ReadonlyArray<Json>>;
  readonly value?: () => Json;
  /**
   * The part the primitive itself considers focused (`trigger`, `tab:1`), or
   * `null`. Preferred over `document.activeElement` so the walk does not race the
   * fixtures' deferred DOM focus (bean 209r).
   */
  readonly focus?: () => string | null;
  readonly dispose: () => void;
}

export interface DomDriverOptions {
  /** Parts that can be hidden: the ones `expect.visible` lists. */
  readonly hideableParts: ReadonlyArray<string>;
  readonly eventName?: (name: string) => string;
}

const BOOLEAN_ATTRS = new Set(["hidden", "disabled"]);
const REFERENCE_ATTRS = new Set([
  "aria-controls",
  "aria-labelledby",
  "aria-owns",
  "aria-activedescendant",
]);
const NAMED_KEYS = new Set(["Enter", "Tab", "Escape", "Backspace", "Delete", "Home", "End"]);

// Solid renders on its own schedule, but `flush()` applies the queued signal work
// synchronously; the fixtures then move DOM focus in a `setTimeout(0)` macrotask
// (kept for user-event's Enter semantics). Waiting one macrotask lets both land
// before the walk reads, without a frame — a frame also lets the browser's focus
// fixup run and perturb the observation (bean 209r). The walk reads focus from
// the fixture's primitive state when it offers one (`Mounted.focus`).
const settle = (): Promise<void> => {
  flush();
  return new Promise((resolve) => {
    setTimeout(resolve, 0);
  });
};

const keyboardSyntax = (key: string): string => {
  if (key === "Space" || key === " ") {
    return " ";
  }
  return NAMED_KEYS.has(key) || key.startsWith("Arrow") || key.startsWith("Page")
    ? `{${key}}`
    : key;
};

// A held key is always written by name: `{Space>}` keeps it down, `{/Space}`
// releases it wherever focus is at that moment (a blur between the two halves
// is exactly what a walk needs to see).
const keyName = (key: string) => (key === " " || key === "Space" ? "Space" : key);

/** `KeyboardEvent.key` uses a space character, not the `Space` alias. */
const eventKey = (key: string) => (key === "Space" ? " " : key);

const CLICKABLE_INPUT_TYPES = new Set([
  "button",
  "color",
  "file",
  "image",
  "reset",
  "submit",
  "checkbox",
  "radio",
]);

/**
 * A half press is dispatched directly (not through user-event's held-key state,
 * which auto-releases on a repeated down and leaks across walk drivers). The
 * two native activations user-event would otherwise add are emulated: Space
 * clicks a button-like element on keyup, Enter on keydown.
 */
const halfPress = (target: EventTarget | null, type: "keydown" | "keyup", key: string) => {
  if (!(target instanceof HTMLElement)) {
    return;
  }
  const keyValue = eventKey(key);
  const notPrevented = target.dispatchEvent(
    new KeyboardEvent(type, {
      key: keyValue,
      code: keyName(key),
      bubbles: true,
      cancelable: true,
    }),
  );
  const clickable =
    target.tagName === "BUTTON" ||
    (target instanceof HTMLInputElement && CLICKABLE_INPUT_TYPES.has(target.type));
  if (
    notPrevented &&
    clickable &&
    ((type === "keyup" && keyValue === " ") || (type === "keydown" && keyValue === "Enter"))
  ) {
    target.click();
  }
};

export const domDriver = (mounted: Mounted, options: DomDriverOptions): Driver => {
  const { root } = mounted;
  const canonical = options.eventName ?? ((name: string) => name);

  const partsOf = (name: string): HTMLElement[] => [
    ...root.querySelectorAll<HTMLElement>(`[data-part="${name}"]`),
  ];

  const targetOf = (element: HTMLElement): string => {
    const name = element.dataset["part"] ?? "";
    return `${name}:${partsOf(name).indexOf(element)}`;
  };

  const elementOf = (target: string): HTMLElement => {
    const [name = "", index = "0"] = target.split(":");
    const element = partsOf(name)[Number(index)];
    if (element === undefined) {
      throw new Unsupported(`part ${target}`);
    }
    return element;
  };

  const click = async (element: HTMLElement): Promise<void> => {
    // a disabled button is not actionable; force lets the browser drop the click itself
    await userEvent.click(element, { force: true });
  };

  // Half presses this driver dispatched a keydown for, so a stray `phase: "up"`
  // stays inert (the spec's key_up only fires on an armed press).
  const halfHeld = new Set<string>();

  return {
    perform: async (step: ActionStep) => {
      switch (step.event) {
        case "focus":
          elementOf(step.target ?? "").focus();
          break;
        case "blur":
          halfHeld.clear();
          elementOf(step.target ?? "").blur();
          break;
        case "click":
          await click(elementOf(step.target ?? ""));
          break;
        case "pointerdown":
          elementOf(step.target ?? "").focus();
          elementOf(step.target ?? "").dispatchEvent(
            new PointerEvent("pointerdown", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          break;
        case "pointerup": {
          const element = elementOf(step.target ?? "");
          element.dispatchEvent(
            new PointerEvent("pointerup", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          // a released pointer button is a click, as the browser would deliver it
          element.click();
          break;
        }
        case "pointercancel":
          elementOf(step.target ?? "").dispatchEvent(
            new PointerEvent("pointercancel", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          break;
        case "hover":
          await userEvent.hover(elementOf(step.target ?? ""));
          break;
        case "unhover":
          await userEvent.unhover(elementOf(step.target ?? ""));
          break;
        case "key": {
          if (step.phase === "down") {
            const element = elementOf(step.target ?? "");
            if (document.activeElement !== element) {
              element.focus();
            }
            // a disabled/read-only control never arms (the spec's spaceArms
            // guard), so a later `up` must not activate it either
            const blocked =
              element.getAttribute("aria-disabled") === "true" ||
              element.getAttribute("aria-readonly") === "true" ||
              (element instanceof HTMLButtonElement && element.disabled);
            if (!blocked) {
              halfHeld.add(keyName(step.key ?? ""));
            }
            halfPress(element, "keydown", step.key ?? "");
            break;
          }
          if (step.phase === "up") {
            if (!halfHeld.delete(keyName(step.key ?? ""))) {
              break;
            }
            // release wherever focus went: deliberately do NOT re-focus the
            // target, or a keydown -> blur -> keyup walk would be defeated
            const active = document.activeElement;
            halfPress(
              active instanceof HTMLElement ? active : document.body,
              "keyup",
              step.key ?? "",
            );
            break;
          }
          const element = elementOf(step.target ?? "");
          if (document.activeElement !== element) {
            element.focus();
          }
          // a whole press releases the key, so a later `phase: "up"` is inert
          halfHeld.delete(keyName(step.key ?? ""));
          await userEvent.keyboard(keyboardSyntax(step.key ?? ""));
          break;
        }
        case "prop":
          if (step.set !== undefined) {
            for (const [name, value] of Object.entries(step.set)) {
              mounted.setProp(name, value);
              if ((name === "disabled" || name === "isDisabled") && value === true) {
                // the spec drops a pending press when the control disables
                halfHeld.clear();
              }
            }
          } else {
            mounted.setProp(step.prop ?? "", step.value);
            if ((step.prop === "disabled" || step.prop === "isDisabled") && step.value === true) {
              halfHeld.clear();
            }
          }
          break;
        default:
          throw new Unsupported(`event ${step.event}`);
      }
      await settle();
    },
    observer: {
      focus: () => {
        // Prefer the primitive's own focus: the fixtures sync DOM focus in a
        // deferred macrotask (kept for user-event's Enter semantics), so reading
        // `document.activeElement` here races that (bean 209r).
        if (mounted.focus !== undefined) {
          return mounted.focus();
        }
        const active = document.activeElement;
        const part =
          active instanceof HTMLElement ? active.closest<HTMLElement>("[data-part]") : null;
        return part !== null && root.contains(part) ? targetOf(part) : null;
      },
      attr: (target, name) => {
        if (name.startsWith("data-")) {
          throw new Unsupported(`styling hook ${name}`);
        }
        const value = elementOf(target).getAttribute(name);
        if (value === null) {
          return null;
        }
        if (value === "" && BOOLEAN_ATTRS.has(name)) {
          return "true";
        }
        if (REFERENCE_ATTRS.has(name)) {
          const referenced = root.querySelector<HTMLElement>(`[id="${value}"]`);
          return referenced?.dataset["part"] === undefined ? value : targetOf(referenced);
        }
        return value;
      },
      visible: () =>
        options.hideableParts.flatMap((name) =>
          partsOf(name)
            .filter((element) => element.checkVisibility())
            .map(targetOf),
        ),
      events: (name) => mounted.events.get(canonical(name)) ?? [],
      ...(mounted.value === undefined ? {} : { value: mounted.value }),
    },
    dispose: mounted.dispose,
  };
};

import {
  type ScenarioConfig,
  ScenarioMismatch,
  differentialWalk,
  parseScenarioFile,
  replayScenario,
  specDriver,
} from "@cssints/apg-specs/scenario";
import {
  checkboxGroupBridge,
  checkboxGroupConfig,
  checkboxGroupProbe,
  checkboxGroupSteps,
} from "@cssints/apg-specs/apg/checkbox-group.bridge";
import { decodeDefinition, makeReferenceModel } from "@quint-machine/core";
import { flush } from "solid-js";
import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import { describe, expect, it } from "vite-plus/test";
import ariakit from "@cssints/apg-specs/scenarios/apg/checkbox.ariakit.json";
import baseUi from "@cssints/apg-specs/scenarios/apg/checkbox.base-ui.json";
import { CheckboxGroup } from "./checkbox-group.tsx";
import definitionJson from "@cssints/apg-specs/apg/checkbox-group.model.json";
import { domDriver } from "./checkbox-group-driver.ts";
import { mountCheckboxGroup } from "./checkbox-group.fixture";
import reactAria from "@cssints/apg-specs/scenarios/apg/checkbox.react-aria.json";

// The copy's own conformance: the same scenarios the primitive is checked against, driven through
// this styled group rather than through the bare controller. The styled group composes the kit's
// `Checkbox`, so the bridge's `checkbox:parent` / `checkbox:0..2` are the four
// `data-part="checkbox"` elements in DOM order, the parent first. The target is translated on the
// way in and every attribute read lands on the skin's own box.
const model = makeReferenceModel(decodeDefinition(definitionJson));

type Driver = ReturnType<typeof domDriver>;

const SHIFT: Readonly<Record<string, string>> = {
  "checkbox:parent": "checkbox:0",
  "checkbox:0": "checkbox:1",
  "checkbox:1": "checkbox:2",
  "checkbox:2": "checkbox:3",
};

const toSkin = (target: string | undefined): string | undefined =>
  target === undefined ? undefined : (SHIFT[target] ?? target);

const translated = (driver: Driver): Driver => ({
  ...driver,
  perform: (step) => {
    const target = toSkin(step.target);
    return driver.perform(target === undefined ? step : { ...step, target });
  },
  observer: {
    ...driver.observer,
    attr: (target, name) => driver.observer.attr(toSkin(target) ?? target, name),
  },
});

const dom = (config: ScenarioConfig) =>
  translated(domDriver(mountCheckboxGroup(checkboxGroupConfig(config)), { hideableParts: [] }));

// Scenarios whose expectations the primitive deliberately does not meet. Each
// entry must still fail (so closing the gap forces removing it) and says why.
const DEFAULT_VALUES =
  "the upstream fixture supplies unstated child values (red/green/blue); without a `values` config the primitive uses its own labels, so the reported value array differs";
const NATIVE_ATTR =
  "react-aria renders native checkboxes; the primitive exposes role=checkbox + aria-checked (APG) and reports onValueChange, not the native checked/onChange pair";
const DIVERGENCES: Readonly<Record<string, string>> = {
  "checkbox.base-ui.group-omitted-defaultvalue": DEFAULT_VALUES,
  "checkbox.react-aria.group-selected-state": NATIVE_ATTR,
};

describe("CheckboxGroup x ported scenarios (real DOM)", () => {
  for (const source of [ariakit, baseUi, reactAria]) {
    const file = parseScenarioFile(source);
    describe(file.source, () => {
      for (const scenario of file.scenarios) {
        it(scenario.id, async (context) => {
          const run = replayScenario(scenario, checkboxGroupBridge, dom);
          const divergence = DIVERGENCES[scenario.id];
          if (divergence !== undefined) {
            await expect(run).rejects.toBeInstanceOf(ScenarioMismatch);
            return;
          }
          const result = await run;
          if (result.status === "unsupported") {
            context.skip(result.reason);
          }
        });
      }
    });
  }
});

describe("CheckboxGroup x the field contract", () => {
  const values: readonly [string, string, string] = ["email", "push", "sms"];

  const mountGroup = (props: {
    label?: string;
    labelledby?: string;
    describedby?: string;
    invalid?: string | boolean;
    error?: string;
    defaultValue?: ReadonlyArray<string>;
  }): HTMLElement => {
    const root = document.createElement("div");
    document.body.append(root);
    render(
      () => (
        <CheckboxGroup
          values={values}
          label={props.label}
          labelledby={props.labelledby}
          describedby={props.describedby}
          invalid={props.invalid}
          error={props.error}
          defaultValue={props.defaultValue}
        >
          {(value) => value}
        </CheckboxGroup>
      ),
      root,
    );
    flush();
    return root;
  };

  const groupOf = (root: HTMLElement): HTMLElement =>
    root.querySelector<HTMLElement>('[data-part="checkbox-group"]')!;
  const errorOf = (root: HTMLElement): HTMLElement =>
    root.querySelector<HTMLElement>('[data-part="checkbox-group-error"]')!;

  it("announces its name, the description the host owns, and its error", () => {
    const root = mountGroup({
      label: "Notifications",
      describedby: "form-hint",
      invalid: true,
      error: "Pick at least one channel",
    });
    const group = groupOf(root);
    const error = errorOf(root);
    expect(group.getAttribute("role")).toBe("group");
    expect(group.getAttribute("aria-label")).toBe("Notifications");
    expect(group.hasAttribute("aria-labelledby")).toBe(false);
    // the error wins over the string `invalid`, and the error id comes first
    expect(group.getAttribute("aria-invalid")).toBe("true");
    expect(group.getAttribute("aria-describedby")).toBe(`${error.id} form-hint`);
    // the error announces itself while it is shown
    expect(error.hasAttribute("hidden")).toBe(false);
    expect(error.getAttribute("role")).toBe("alert");
    expect(error.textContent).toBe("Pick at least one channel");
  });

  it("names the group from a host element, and stays quiet while it is valid", () => {
    const root = mountGroup({
      labelledby: "channels-title",
      // `invalid: false` wins over a message: the host keeps the text ready
      invalid: false,
      error: "Pick at least one channel",
    });
    const group = groupOf(root);
    const error = errorOf(root);
    expect(group.getAttribute("aria-labelledby")).toBe("channels-title");
    expect(group.hasAttribute("aria-label")).toBe(false);
    expect(group.hasAttribute("aria-invalid")).toBe(false);
    expect(group.hasAttribute("aria-describedby")).toBe(false);
    expect(error.hasAttribute("hidden")).toBe(true);
    expect(error.hasAttribute("role")).toBe(false);
    expect(error.textContent).toBe("");
  });

  it("keeps the announced attributes on the group, not on the boxes", () => {
    const root = mountGroup({ label: "Notifications", invalid: true });
    const group = groupOf(root);
    expect(group.getAttribute("aria-invalid")).toBe("true");
    // no error message: the group is marked, and nothing is described
    expect(group.hasAttribute("aria-describedby")).toBe(false);
    expect(errorOf(root).hasAttribute("hidden")).toBe(true);
    for (const box of root.querySelectorAll<HTMLElement>('[data-part="checkbox"]')) {
      expect(box.hasAttribute("aria-invalid")).toBe(false);
    }
  });

  it("gives two groups on one page distinct ids", () => {
    const first = mountGroup({ label: "Channels" });
    const second = mountGroup({ label: "Topics" });
    expect(groupOf(first).id).not.toBe("");
    expect(groupOf(first).id).not.toBe(groupOf(second).id);
  });
});

describe("CheckboxGroup x spec (differential walk)", () => {
  const base: ScenarioConfig = {
    group: true,
    parent: true,
    values: ["0", "1", "2"],
  };
  for (const config of [
    base,
    { ...base, remember: true },
    { ...base, parent: false },
    { group: true, values: ["0", "1", "2"] },
    // controlled: a host that accepts every request, and one that holds
    { ...base, value: ["0"] },
    { ...base, value: ["0", "2"] },
    { ...base, controlled: true, accepts: true },
    { ...base, controlled: true, accepts: false, value: ["1"] },
  ]) {
    it(`matches the generated model for ${JSON.stringify(config)}`, async () => {
      await differentialWalk({
        alphabet: checkboxGroupSteps,
        probe: checkboxGroupProbe,
        makePair: () =>
          Promise.resolve([specDriver(model, checkboxGroupBridge, config), dom(config)]),
        runs: 15,
        steps: 25,
        seed: 7,
      });
    });
  }
});

// The skin's own contract: one `role="group"` around the kit's boxes, the tri-state parent box
// drawn from `aria-checked`, and the error element the primitive's `aria-describedby` names.
const mount = (view: () => JSX.Element): HTMLElement => {
  const root = document.createElement("div");
  document.body.append(root);
  render(view, root);
  flush();
  return root;
};

const boxesOf = (root: HTMLElement): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="checkbox"]'),
];

describe("CheckboxGroup skin", () => {
  it("renders three of the kit's boxes with the tri-state parent above them", () => {
    const root = mount(() => (
      <CheckboxGroup
        label="Notifications"
        values={["email", "push", "sms"]}
        parent
        defaultValue={["email"]}
      >
        {(value) => value}
      </CheckboxGroup>
    ));
    const group = root.querySelector<HTMLElement>('[data-part="checkbox-group"]')!;
    expect(group.getAttribute("role")).toBe("group");
    expect(group.getAttribute("aria-label")).toBe("Notifications");
    const boxes = boxesOf(root);
    expect(boxes.length).toBe(4);
    // the parent first, derived from the children: one of three is mixed
    expect(boxes.map((box) => box.getAttribute("aria-checked"))).toEqual([
      "mixed",
      "true",
      "false",
      "false",
    ]);
    expect(new Set(boxes.map((box) => box.getAttribute("role")))).toEqual(new Set(["checkbox"]));
  });

  it("toggles one box without the others, and the parent follows", () => {
    const root = mount(() => (
      <CheckboxGroup label="Notifications" values={["email", "push", "sms"]} parent>
        {(value) => value}
      </CheckboxGroup>
    ));
    const boxes = boxesOf(root);
    boxes[1]!.click();
    flush();
    expect(boxes.map((box) => box.getAttribute("aria-checked"))).toEqual([
      "mixed",
      "true",
      "false",
      "false",
    ]);
    boxes[2]!.click();
    flush();
    boxes[3]!.click();
    flush();
    expect(boxes.map((box) => box.getAttribute("aria-checked"))).toEqual([
      "true",
      "true",
      "true",
      "true",
    ]);
    // the parent is off: the next press turns every child off
    boxes[0]!.click();
    flush();
    expect(boxes.map((box) => box.getAttribute("aria-checked"))).toEqual([
      "false",
      "false",
      "false",
      "false",
    ]);
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
